INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28101, 'Ephesians 2:5', 'Ephesians', 2, 5, '&nbsp;تر دې پورې کله چې مونږ د نافرمانو په وجه مړۀ وُو نو هغۀ مونږ د مسيح سره بيا راژوندى کړُو. او د فضل په وسيله تاسو خلاصون بياموندو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28102, 'Ephesians 2:6', 'Ephesians', 2, 6, '&nbsp;خُدائ پاک مونږ د عيسىٰ مسيح سره د مړو نه راوچت کړُو او په آسمان کښې يې د هغۀ سره په تخت کښېنولو، ځکه چې مونږ د مسيح سره يو شوى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28103, 'Ephesians 2:7', 'Ephesians', 2, 7, '&nbsp;نو خُدائ پاک په ټولو راتلونکو زمانو کښې هغه خپل بې‌اندازې لوئ فضل چې مونږ ته يې راکوى د عيسىٰ مسيح په وسيله به يې مونږ ته په خپل رحم کښې راښکاره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28104, 'Ephesians 2:8', 'Ephesians', 2, 8, '&nbsp;ځکه چې خُدائ پاک د خپل فضل په سبب تاسو له د ايمان په وجه خلاصون درکړو، او دا ستاسو خپل کار نۀ وو، بلکې دا د خُدائ پاک د خوا نه انعام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28105, 'Ephesians 2:9', 'Ephesians', 2, 9, '&nbsp;خلاصون زمونږ د نېک عمل اجر نۀ دے نو په مونږ کښې دې څوک هم په خپل عمل فخر ونۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28106, 'Ephesians 2:10', 'Ephesians', 2, 10, '&nbsp;ځکه چې مونږ د هغۀ خاص مخلوق يُو چا چې مونږ په عيسىٰ مسيح کښې د نېکو کارونو دپاره پېدا کړى يُو، او دا کارونه خُدائ پاک د مخکښې نه زمونږ دپاره تيار کړى وُو، چې مونږ يې سر ته ورسوو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28107, 'Ephesians 2:11', 'Ephesians', 2, 11, '&nbsp;نو بيا دا خبره مۀ هېروئ چې يو وخت تاسو غېر‌يهوديان هم بې‌خُدايه ګڼلے شوئ. او يهوديانو به تاسو ته ناسنته او د کافر آواز کولو، اګر چې دې سنت صرف د هغوئ بدن متاثره کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28108, 'Ephesians 2:12', 'Ephesians', 2, 12, '&nbsp;نو بيا تاسو په هغه زمانه کښې د مسيح نه جدا وئ، او تاسو د بنى اِسرائيلو د قوميت نه بهر وئ، او تاسو د تړون د وعدې نه ناخبره وئ کومه چې خُدائ پاک د هغوئ سره کړې وه. او په دُنيا کښې مو نا اُميده او بې‌خُدايه ژوند کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28109, 'Ephesians 2:13', 'Ephesians', 2, 13, '&nbsp;خو اوس تاسو د عيسىٰ مسيح سره يو شوى يئ. تاسو يو وخت د خُدائ پاک نه لرى وئ، خو اوس د مسيح د وينې په وسيله د هغۀ سره نزدې شوى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28110, 'Ephesians 2:14', 'Ephesians', 2, 14, '&nbsp;ځکه چې مسيح په خپله زمونږ صُلح وکړه. هغۀ يهوديان او غېر‌يهوديان د خپل بدن په وسيله په سولۍ يو ځائ کړل، او د دشمنۍ هغه دېوال يې ونړولو کوم چې مونږ جدا کړى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28111, 'Ephesians 2:15', 'Ephesians', 2, 15, '&nbsp;هغۀ شريعت سره د دې د حکمونو او قانون منسوخ کړو. هغۀ په خپل ځان کښې د يهوديانو او غېر‌يهوديانو دوه قبيلې يو او نوے خلقت کړل او صُلح يې په کښې راوسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28112, 'Ephesians 2:16', 'Ephesians', 2, 16, '&nbsp;په سولۍ باندې مسيح د خپل مرګ په وسيله دواړه قبيلې په خپل بدن کښې يو کړې او د خُدائ پاک سره يې پخلا کړې، او کومه دشمنى چې يې په خپلو کښې کوله هغه يې د مرګ تيارو ته وغورزوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28113, 'Ephesians 2:17', 'Ephesians', 2, 17, '&nbsp;هغۀ دا د صُلحې زيرے تاسو غېر‌يهوديانو ته څوک چې لرى وئ او يهوديانو ته چې نزدې وُو واورولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28114, 'Ephesians 2:18', 'Ephesians', 2, 18, '&nbsp;ځکه چې د مسيح په وسيله مونږ دواړه په يو روح کښې د پلار په حضور کښې حاضرېدے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28115, 'Ephesians 2:19', 'Ephesians', 2, 19, '&nbsp;نو اوس بيا تاسو نور پردى او مسافر نۀ يئ بلکې د مقدسينو هم مُلک او د خُدائ پاک د خاندان کسان يئ', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28116, 'Ephesians 2:20', 'Ephesians', 2, 20, '&nbsp;نو تاسو د رسولانو او نبيانو په بنياد ودان کړے شوى يئ چې عيسىٰ مسيح يې په خپله د ګوټ سر کاڼے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28117, 'Ephesians 2:21', 'Ephesians', 2, 21, '&nbsp;په هغۀ کښې د عمارت ټولې برخې رايوځائ کيږى او ترې نه د مالِک مقدس کور جوړيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28118, 'Ephesians 2:22', 'Ephesians', 2, 22, '&nbsp;نو تاسو هم د هغۀ په يووالى کښې د نورو سره د خُدائ پاک يو داسې کور جوړوئ چې په کوم کښې خُدائ پاک د خپل روح په وسيله اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28119, 'Ephesians 3:1', 'Ephesians', 3, 1, '&nbsp;هم دا وجه ده چې زۀ پولوس چې ستاسو غېر‌يهوديانو د خاطره د عيسىٰ مسيح قېدى يم تاسو ته دُعا کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28120, 'Ephesians 3:2', 'Ephesians', 3, 2, '&nbsp;ضرور به تاسو د خُدائ پاک د هغه فضل د ذمه وارۍ په حقله کوم چې ستاسو دپاره ما ته راکړے شوے دے اورېدلې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28121, 'Ephesians 3:3', 'Ephesians', 3, 3, '&nbsp;لکه څنګه چې ما تاسو ته مخکښې په لنډه توګه وليکل دا هغه راز دے چې خُدائ پاک په خپله د الهام په وسيله ما ته وښودلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28122, 'Ephesians 3:4', 'Ephesians', 3, 4, '&nbsp;ما چې تاسو ته څۀ ليکلى دى کله چې تاسو هغه وايئ نو په دې به پوهه شئ چې ما ته د مسيح د پټ راز څومره عِلم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28123, 'Ephesians 3:5', 'Ephesians', 3, 5, '&nbsp;هغه راز دا دے چې په تېرو زمانو کښې بنى آدمو ته دغه شان نۀ وو ښکاره شوے څنګه چې دا راز اوس پاکو رسولانو او نبيانو ته د روحُ القُدس په وسيله ښکاره کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28124, 'Ephesians 3:6', 'Ephesians', 3, 6, '&nbsp;او هغه راز دا دے چې کومو يهوديانو او غېر‌يهوديانو چې په زېرى ايمان راوړے وى هغوئ دواړه د خُدائ پاک په ميراث کښې برابر شريک دى، او دوئ د يو بدن اندامونه دى، او دواړه د عيسىٰ مسيح په وسيله د برکت په وعدې کښې شريک دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28125, 'Ephesians 3:7', 'Ephesians', 3, 7, '&nbsp;ما ته د خُدائ پاک په فضل او لوئ قدرت سره د زيرى د اورولو د خِدمت حق راکړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28126, 'Ephesians 3:8', 'Ephesians', 3, 8, '&nbsp;اګر کۀ زۀ په ټولو مقدسينو کښې د ټولو ورکوټو نه ورکوټے يم، خو دا فضل په ما وشو چې زۀ غېر‌يهوديانو ته د مسيح د بې‌اندازې دولت زيرے ورکړم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28127, 'Ephesians 3:9', 'Ephesians', 3, 9, '&nbsp;او چې هغه پټ راز ټولو خلقو ته ښکاره کړم کوم چې خُدائ پاک، د ټولو څيزونو خالق د ازل نه پټ ساتلے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28128, 'Ephesians 3:10', 'Ephesians', 3, 10, '&nbsp;په دې هر څۀ کښې د خُدائ پاک مقصد دا وو چې د جماعت په وسيله خپل هر قسمه حکمت هغه ناليدونکو حاکمانو او د واک خاوندانو ته چې په آسمانى ځايونو کښې دى ښکاره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28129, 'Ephesians 3:11', 'Ephesians', 3, 11, '&nbsp;دا د هغه ابدى ارادې په مطابق وو کومه چې هغۀ زمونږ په مالِک عيسىٰ مسيح کښې پوره کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28130, 'Ephesians 3:12', 'Ephesians', 3, 12, '&nbsp;نو مونږ په مسيح کښې او په هغۀ د ايمان په وسيله په زړۀ ورتيا او په ډاډ سره د خُدائ پاک په مخکښې حاضرېدے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28131, 'Ephesians 3:13', 'Ephesians', 3, 13, '&nbsp;نو زۀ تاسو ته خواست کوم چې زما د مصيبتونو په ليدو سره مۀ بې‌زړۀ کېږئ. ځکه زۀ دا ستاسو دپاره برداشت کوم، او دا دې ستاسو د عزت باعث وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28132, 'Ephesians 3:14', 'Ephesians', 3, 14, '&nbsp;په هم دې وجه زۀ د پلار په وړاندې دُعا کوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28133, 'Ephesians 3:15', 'Ephesians', 3, 15, '&nbsp;د چا نه چې په آسمان او زمکه کښې هر قوم خپل حقيقى نوم مومى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28134, 'Ephesians 3:16', 'Ephesians', 3, 16, '&nbsp;زۀ دُعا کوم چې هغه د خپل لوئ جلال په مطابق تاسو ته هغه څۀ درکړى چې تاسو په خپل باطنى انسانيت کښې د هغۀ د روح په وسيله ډېر قوى شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28135, 'Ephesians 3:17', 'Ephesians', 3, 17, '&nbsp;نو چې بيا د ايمان په وسيله مسيح ستاسو په زړونو کښې واوسيږى، او زما دا دُعا ده چې د خُدائ پاک په مينه کښې ستاسو جرړې مضبوطې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28136, 'Ephesians 3:18', 'Ephesians', 3, 18, '&nbsp;او زۀ دُعا کوم چې تاسو سره هم دا قدرت راشى چې د ټولو مقدسينو سره يو ځائ پوهه شئ چې د مسيح د مينې پلنوالے، اوږدوالے، اوچتوالے او ژوروالے څومره دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28137, 'Ephesians 3:19', 'Ephesians', 3, 19, '&nbsp;او چې د مسيح په هغه مينه پوهه شئ چې د پوهې نه بهر ده، او چې تاسو د خُدائ پاک د پوره معمورۍ نه ډک شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28138, 'Ephesians 3:20', 'Ephesians', 3, 20, '&nbsp;د خُدائ پاک جلال دې وى څوک چې قادر دے او د هغه قدرت په وسيله چې په مونږ کښې کار کوى هغه زمونږ د منت او خيال نه ډېر زيات کار کولے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28139, 'Ephesians 3:21', 'Ephesians', 3, 21, '&nbsp;هغۀ ته دې په جماعت کښې او په عيسىٰ مسيح کښې د تل دپاره نسل در نسل جلال وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28140, 'Ephesians 4:1', 'Ephesians', 4, 1, '&nbsp;نو زۀ چې د مالِک د خاطره قېدى يم، په تاسو زور راوړم چې هغه شان نېک ژوند تېروئ د کوم دپاره چې خُدائ پاک تاسو رابللى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28141, 'Ephesians 4:2', 'Ephesians', 4, 2, '&nbsp;په پوره عاجزۍ، نرمۍ، صبر او په مينې سره يو بل زغمئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28142, 'Ephesians 4:3', 'Ephesians', 4, 3, '&nbsp;پوره کوشش کوئ چې په خپلو کښې د روحُ القُدس يووالے د سلامتۍ د تړون په وسيله قائم وساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28143, 'Ephesians 4:4', 'Ephesians', 4, 4, '&nbsp;بدن هم يو دے او روحُ القُدس هم يو دے او دغه شان تاسو هم د يو اُميد دپاره رابللے شوى وئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28144, 'Ephesians 4:5', 'Ephesians', 4, 5, '&nbsp;يو مالِک دے، يو ايمان، يوه بپتسمه ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28145, 'Ephesians 4:6', 'Ephesians', 4, 6, '&nbsp;او واحد خُدائ پاک، چې د ټولو اېک يو پلار دے، څوک چې د ټولو دپاسه، او د ټولو په وسيله کار کوى او په ټولو کښې موجود دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28146, 'Ephesians 4:7', 'Ephesians', 4, 7, '&nbsp;خو مونږ هر يو ته د مسيح د سخاوت په مطابق نعمتونه راکړے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28147, 'Ephesians 4:8', 'Ephesians', 4, 8, '&nbsp;هم دغه وجه ده چې کلام دا فرمائى چې، ”کله چې هغه بره لاړو قېديان يې د ځان سره بوتلل، او خلقو له يې تحفې ورکړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28148, 'Ephesians 4:9', 'Ephesians', 4, 9, '&nbsp;د هغۀ د بره ختلو نه څۀ مطلب دے بې له دې نه چې هغه د زمکې ښکته برخې ته هم کوز شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28149, 'Ephesians 4:10', 'Ephesians', 4, 10, '&nbsp;او هغه څوک چې ښکته راکوز شو هم هغه د ټولو آسمانونو نه بره وختو، د دې دپاره چې ټول کائنات د خپل حضور نه ډک کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28150, 'Ephesians 4:11', 'Ephesians', 4, 11, '&nbsp;دا هم هغه هستى وه چې نعمتونه يې خلقو له ورکړل چې څوک به رسولان، څوک به نبيان، او څوک به د زيرى اورونکى، او څوک به د ايماندارانو شپونکى، او څوک به اُستاذان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28151, 'Ephesians 4:12', 'Ephesians', 4, 12, '&nbsp;د هغوئ ذمه وارى دا ده چې مقدسين د خِدمت دپاره تيار کړى او د مسيح بدن له وده ورکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28152, 'Ephesians 4:13', 'Ephesians', 4, 13, '&nbsp;ترڅو مونږ ټول په ايمان راوړلو کښې يو شُو او د خُدائ پاک زوئ په ښۀ شان وپېژنو، او ايمان کښې بالغان شُو، او د مسيح پوره کاملېدو ته ورسيږو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28153, 'Ephesians 4:14', 'Ephesians', 4, 14, '&nbsp;نو په کار نۀ دے چې مونږ دې نور ماشومان پاتې شُو. او نۀ دې مونږ د نوى تعليماتو په وجه اخوا دېخوا کيږُو او نۀ به نور د خلقو د مکارۍ، چالاکۍ او ټګۍ په منصوبو سره ګمراه شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28154, 'Ephesians 4:15', 'Ephesians', 4, 15, '&nbsp;نو د دې په ځائ مونږ ته په مينه کښې حقيقت وئيل په کار دى، او په مسيح کښې به وده وکړُو، څوک چې زمونږ سر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28155, 'Ephesians 4:16', 'Ephesians', 4, 16, '&nbsp;هغه په خپله ټول بدن په کاملې طريقې سره يو ځائ کوى، چې دغه شان هره حِصه خپل خاص کار سر ته رسوى، او د بدن د نورو حِصو سره په ترقۍ کولو کښې مدد کوى، د دې دپاره چې ټول بدن صحتمند او پوره په مينې سره وده وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28156, 'Ephesians 4:17', 'Ephesians', 4, 17, '&nbsp;نو زۀ تاسو ته په مالِک کښې په سختۍ سره دا خبره کوم چې تاسو نور د غېر‌يهوديانو په شان مۀ اوسېږئ، لکه څنګه چې هغوئ په خپلو باطلو خيالاتو کښې اوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28157, 'Ephesians 4:18', 'Ephesians', 4, 18, '&nbsp;هغوئ د خپلو سوچونو په تيارو کښې ډوب شوى دى او کوم ژوند چې خُدائ پاک ورکوى نو د جاهليت او د هغوئ د زړونو د سختوالى په وجه هغوئ د هغې نه لرې شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28158, 'Ephesians 4:19', 'Ephesians', 4, 19, '&nbsp;هغوئ نۀ شرميږى او خپل ځانونه يې په شهوت پرستۍ، او په هر قسم ګنده کارونو پسې ليونى کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
