(28160, 'Ephesians 4:21', 'Ephesians', 4, 21, '&nbsp;د کله نه چې تاسو د عيسىٰ په حقله اورېدلى دى او هغه حقيقت مو زده کړے دے کوم چې د هغۀ نه راځى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28161, 'Ephesians 4:22', 'Ephesians', 4, 22, '&nbsp;نو خپل زوړ د ګناه فطرت او پخوانۍ د ژوند تېرولو طريقې پرېږدئ کوم چې په دوکه او شهوت پرستۍ خرابې شوې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
