(28164, 'Ephesians 4:25', 'Ephesians', 4, 25, '&nbsp;نو بيا تاسو هر يو کس دروغ وئيل پرېږدئ او د خپل ګاونډى سره رښتيا وايئ ځکه چې مونږ ټول د يو بدن اندامونه يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28165, 'Ephesians 4:26', 'Ephesians', 4, 26, '&nbsp;د غصې په وخت کښې ګناه مۀ کوئ او خپله غصه د نمر د پرېوتو نه اخوا مۀ پرېږدئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
